/**
 * The built client must not include fixture modules or the golden answer key.
 * Unit tests and Storybook may. `pnpm check:bundle` reads the Rollup module
 * graph written by the app build, then scans dist for the golden values.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const goldenValues = ["37700", "134520", "2389917160", "2393153301", "2379562633", "114000"];
const fixtureSentence =
  "שיפוץ דירה + לובי בבניין ברחוב הרצל 12, רמת גן. הלקוח העיקרי יזמות הגליל; ד.ל. נכסים (חברת הניהול) הזמינה תוספות בלובי.";
const flowTest2Sentence = "Generated by `pnl.py` from `dataset.py` + `state.json`.";

const modulePatterns = [
  /[/\\]fixtures[/\\]/,
  /expected-pnl/,
  /\.stories\.(tsx?|jsx?|mdx)/,
  /[/\\]demo[/\\]/,
  /[/\\]demo[^/\\]*\.(tsx?|jsx?|mjs)/,
  /@flow[/\\]shared[/\\]testing/,
  /[/\\]testing\.ts$/,
  /[/\\]reviewer-preview\./,
  /[/\\]reviewer-sample\./,
];

/**
 * @param {{ modules: string[], files: { name: string, body: string }[] }} input
 * @returns {string[]}
 */
const sourceMarkers = [
  ["flow-test", (body) => body.includes("flow-test")],
  ["2389917160", (body) => body.includes("2389917160")],
  ["2393153301", (body) => body.includes("2393153301")],
  ["2379562633", (body) => body.includes("2379562633")],
  ["114000", (body) => body.includes("114000")],
  ["draft:", (body) => body.includes("draft:")],
  ["Flow Test 2 fixture", (body) => body.includes(flowTest2Sentence)],
  ["FLOW_TEST_", (body) => body.includes("FLOW_TEST_")],
  ["fixtures/", (body) => body.includes("fixtures/") || body.includes("fixtures\\")],
  ["expected-pnl", (body) => body.includes("expected-pnl")],
  ["demo-data", (body) => body.includes("demo-data")],
  ["fixture sentence", (body) => body.includes(fixtureSentence)],
];

export function violations(input) {
  const found = [];
  for (const id of input.modules) {
    if (modulePatterns.some((pattern) => pattern.test(id))) {
      found.push(`module graph includes ${id}`);
    }
  }
  for (const file of input.files) {
    if (
      file.body.includes("demo-data")
      || file.body.includes("expected-pnl")
      || file.body.includes(fixtureSentence)
      || file.body.includes(flowTest2Sentence)
    ) {
      found.push(`${file.name} contains a fixture marker`);
    }
    for (const value of goldenValues) {
      if (file.body.includes(value)) found.push(`${file.name} contains golden value ${value}`);
    }
    if (file.body.includes("Example data")) found.push(`${file.name} contains Example data`);
    if (file.body.includes("/e2e/")) found.push(`${file.name} contains /e2e/`);
    for (const marker of ["sampleSaveMode", "sampleRun", "reviewerBooks", "reviewerQueue", "reviewer-preview", "reviewer-sample"]) {
      if (file.body.includes(marker)) found.push(`${file.name} contains ${marker}`);
    }
    if (file.body.includes("new-")) found.push(`${file.name} contains a story id prefix`);
    if (file.body.includes("draft:")) found.push(`${file.name} contains a story id prefix`);
  }
  return found;
}

/** Edge Function sources. Fixed Flow Test data must not ship in the runtime. */
export function sourceViolations(files) {
  const found = [];
  for (const file of files) {
    for (const [name, hit] of sourceMarkers) {
      if (hit(file.body)) found.push(`${file.name} contains ${name}`);
    }
  }
  return found;
}

function scanTree(dir, pattern) {
  /** @type {{ name: string, body: string }[]} */
  const files = [];
  if (!existsSync(dir)) return files;
  const walk = (current) => {
    for (const name of readdirSync(current)) {
      const full = path.join(current, name);
      if (statSync(full).isDirectory()) {
        walk(full);
        continue;
      }
      if (!pattern.test(name)) continue;
      files.push({ name: path.relative(root, full), body: readFileSync(full, "utf8") });
    }
  };
  walk(dir);
  return files;
}

function scanDist(dist) {
  /** @type {{ name: string, body: string }[]} */
  const files = [];
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const full = path.join(dir, name);
      if (statSync(full).isDirectory()) {
        walk(full);
        continue;
      }
      if (!/\.(js|css|html|webmanifest|json)$/.test(name)) continue;
      files.push({ name: path.relative(root, full), body: readFileSync(full, "utf8") });
    }
  };
  if (existsSync(dist)) walk(dist);
  return files;
}

/** Names from the Flow Test 2 books. A reviewers-only dist must not contain them. */
export const flowTest2Names = [
  "שיפוץ הרצל",
  "הובלות הגליל",
  "מנופי המרכז",
  "השרון",
  "יזמות הגליל",
  "פרגולות הגליל",
  "לוי רעננה",
  "ביאליק",
  "פרגולה בית כהן",
];

/**
 * @param {{ name: string, body: string }[]} files
 * @returns {string[]}
 */
export function reviewerNameViolations(files) {
  const found = [];
  for (const file of files) {
    for (const name of flowTest2Names) {
      if (file.body.includes(name)) found.push(`${file.name} contains Flow Test 2 name ${name}`);
    }
  }
  return found;
}

export function checkReviewerBundle() {
  const dist = path.join(root, "app/dist");
  if (!existsSync(dist)) return ["app/dist is missing. Build the reviewers-only bundle first."];
  return reviewerNameViolations(scanDist(dist));
}

export function checkProductionBundle() {
  const dist = path.join(root, "app/dist");
  const graphPath = path.join(root, "app/bundle-graph.json");
  /** @type {string[]} */
  const problems = [];
  if (!existsSync(dist)) problems.push("app/dist is missing. Run pnpm build before this check.");
  if (!existsSync(graphPath)) {
    problems.push("app/bundle-graph.json is missing. The production build must record its module graph outside dist.");
    return problems;
  }
  const modules = JSON.parse(readFileSync(graphPath, "utf8"));
  if (!Array.isArray(modules)) {
    problems.push("bundle-graph.json is not a list of module ids");
    return problems;
  }
  return [
    ...violations({ modules, files: scanDist(dist) }),
    ...sourceViolations(scanTree(path.join(root, "supabase/functions"), /\.(ts|tsx|js|mjs)$/)),
  ];
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const reviewer = process.argv.includes("--reviewer");
  const bad = reviewer ? checkReviewerBundle() : checkProductionBundle();
  if (bad.length > 0) {
    console.error(bad.join("\n"));
    process.exit(1);
  }
  console.log(reviewer
    ? "reviewer dist has no Flow Test 2 names"
    : "production graph and dist have no fixtures or golden values");
}
